var o=[{title:`Stretching statico`,text:`Uno stretching statico mantiene con delicatezza un muscolo o un’articolazione vicino al limite del suo range comodo. Uno stretching del polpaccio contro un muro o un allungamento del flessore dell’anca con appoggio, per esempio, può essere mantenuto per poco tempo senza molleggiare. Dovrebbe sembrare una lieve tensione, mai dolore acuto o intorpidimento.`},{title:`Stretching dinamico`,text:`Lo stretching dinamico attraversa un range utile più e più volte: oscillazioni delle gambe che riesci a controllare, cerchi con le braccia, affondi alternati. Ogni ripetizione è deliberata, senza molleggi né fretta. Questi esercizi rientrano naturalmente in un riscaldamento per corsa, sollevamento e sport.`},{title:`Quando usare ciascuno`,text:`Prima di uno sforzo esplosivo, un movimento dinamico graduale e la pratica dell’esercizio stesso di solito funzionano meglio. Uno stretching statico lungo e intenso subito prima può ridurre brevemente forza o potenza, mentre poche tenute brevi sono meno preoccupanti. Dopo l’allenamento o in una sessione separata, lo stretching statico è un modo ragionevole per lavorare sulla flessibilità.`},{title:`Quanto farne`,text:`Usa tenute brevi e comode e ripetile nel corso delle settimane invece di forzare un nuovo range in una sola sessione. Per gli esercizi dinamici, inizia con un piccolo range e ampliarlo solo finché il movimento resta controllato. Lo stretching non deve far male per funzionare, e più flessibilità non aiuta ogni compito.`},{title:`Cosa lo stretching non può promettere`,text:`Usa esercizi dinamici per prepararti al movimento attivo e tenute statiche quando l’obiettivo è la flessibilità. Nessuno dei due ti rende a prova di infortunio né previene in modo affidabile il dolore muscolare. Se il dolore persiste, chiedi a un medico o a un fisioterapista un consiglio adatto a te.`}];var t=[{label:`ACE 2026: indicazioni pratiche sullo stretching`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`ACE 2026: mobilità e flessibilità a confronto`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`NHS: esercizi leggeri di defaticamento`,url:`https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/`}];var n={sections:o,sources:t};export{n as default,o as sections,t as sources};